import numpy as np
from scipy import stats
from sklearn.feature_selection import mutual_info_classif
from collections import defaultdict

MAX_DRIVERS = 2

def design(feats):
    # Compute effect sizes and p-values for each feature
    effects = []
    for i, fid in enumerate(feats.ids):
        x = feats.x[:, i]
        y = feats.y
        mean1 = np.mean(x[y == 1])
        mean0 = np.mean(x[y == 0])
        effect_size = mean1 - mean0
        t_stat, p_val = stats.ttest_ind(x[y == 1], x[y == 0], equal_var=False)
        auc = roc_auc_score(y, x) if len(np.unique(y)) == 2 else 0.5
        effects.append((fid, effect_size, abs(t_stat), p_val, auc))

    # Sort by effect size (descending)
    effects.sort(key=lambda x: abs(x[1]), reverse=True)

    # Select top features
    candidates = [f for f, _, _, p, _ in effects if p < 0.05]

    # Remove near-duplicates based on correlation
    selected = []
    correlated = set()
    for fid in candidates:
        if fid in correlated:
            continue
        selected.append(fid)
        # Find correlated features to exclude
        for other_fid in candidates:
            if other_fid != fid and other_fid not in correlated:
                idx1 = feats.column(fid)
                idx2 = feats.column(other_fid)
                corr = np.corrcoef(feats.x[:, idx1], feats.x[:, idx2])[0, 1]
                if abs(corr) >= 0.6:
                    correlated.add(other_fid)
        if len(selected) >= MAX_DRIVERS:
            break

    # If no strong signal, return empty design
    if len(selected) == 0:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Build regression components
    columns = selected[:]
    products = []
    loadings = {}

    # Add interaction terms if we have more than one driver
    if len(selected) > 1:
        for i in range(len(selected)):
            for j in range(i+1, len(selected)):
                products.append((selected[i], selected[j]))

    # Weighted score using first feature
    if selected:
        loadings[selected[0]] = 1.0

    return Design(
        drivers=tuple(selected),
        columns=tuple(columns),
        products=tuple(products),
        loadings=loadings
    )

# Helper function for AUC calculation
def roc_auc_score(y_true, y_score):
    try:
        from sklearn.metrics import roc_auc_score as sk_auc
        return sk_auc(y_true, y_score)
    except ImportError:
        # Simple approximation if sklearn not available
        return 0.5

